            : {}),
        cwd: spec.cwd,
        root: spec.root,
        recordedAt: new Date(now()).toISOString(),
        projectRootHash: spec.projectRootHash,
      },
      {
        runner: deps.runner,
        onProcessSpawn: identity => {
