            schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
            runId: spec.runId,
            at: new Date(now()).toISOString(),
            type: 'provider_spawned',
            detail: {
              pid: identity.pid,
              pgid: identity.pgid,
              processGroupIsolated: identity.processGroupIsolated,
